def best_move(grid, prev_move=None):
    n = len(grid)
    sqrt_n = int(n**0.5)

    def is_valid(grid, row, col, num):
        for i in range(n):
            if grid[row][i] == num or grid[i][col] == num:
                return False
        start_row, start_col = row - row % sqrt_n, col - col % sqrt_n
        for i in range(sqrt_n):
            for j in range(sqrt_n):
                if grid[i + start_row][j + start_col] == num:
                    return False
        return True

    def possible_moves(grid, prev_move):
        if prev_move is None:
            return [(i, j) for i in range(n) for j in range(n) if grid[i][j] == 0]
        prev_row, prev_col = prev_move[0], prev_move[1]
        valid_moves = [(i, j) for i in range(n) for j in range(n) if grid[i][j] == 0 and (i == prev_row or j == prev_col or grid[prev_row][j] == 0 or grid[i][prev_col] == 0)]
        return valid_moves

    def blocker_count(valid_moves, potential_edges):
        count = 0
        for move in valid_moves:
            x, y = move
            for edge in potential_edges:
                if grid[x][y] not in edge:
                    count += 1
        return count

    remaining_moves = possible_moves(grid, prev_move)
    if not remaining_moves:
        return [(0, 0), 1]  # Move to any empty cell 1 (arbitrary choice)

    blocker_counts = []
    for move in remaining_moves:
        x, y = move
        if is_valid(grid, x, y, grid[prev_move[0]][prev_move[1]]+1):
            pass_count = blocker_count(remaining_moves, [(x, y) for x, y in remaining_moves if is_valid(grid, x, y, grid[prev_move[0]][prev_move[1]]+1)])
            blocker_counts.append((move, pass_count))

    best_move = max(blocker_counts, key=lambda x: x[1])[0]
    next_value = grid[prev_move[0]][prev_move[1]] + 1 if prev_move else 1
    return [best_move, next_value]

